<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { AlertCircle,BadgeCheck,BriefcaseBusiness,ChevronRight,Circle,Play,RefreshCw,Route,ShieldCheck } from '@lucide/vue'
import { createEnterpriseJourney,getEnterpriseJourneyWorkspace,recordEnterpriseJourneyVisit } from '../api/competitionJourney'

const router=useRouter()
const workspace=ref({organizations:[],runs:[],truthfulness:null})
const selectedRunId=ref(localStorage.getItem('edumatrix_enterprise_journey_id')||'')
const organizationId=ref(localStorage.getItem('edumatrix_enterprise_journey_org')||'')
const learnerId=ref(localStorage.getItem('edumatrix_enterprise_journey_learner')||'')
const loading=ref(true),action=ref(''),error=ref(''),notice=ref('')
const run=computed(()=>workspace.value.runs.find(item=>item.id===selectedRunId.value)||null)
const organization=computed(()=>workspace.value.organizations.find(item=>item.id===organizationId.value)||null)
const learners=computed(()=>organization.value?.learners||[])
const nextStep=computed(()=>run.value?.steps.find(item=>!item.complete)||null)

function detail(e){const d=e?.detail||e?.response?.data?.detail;return d?.message||(typeof d==='string'?d:'')||e?.message||'操作失败'}
function applyRunContext(item){const context=item?.enterprise_context;if(!context)return;organizationId.value=context.organization_id||'';learnerId.value=context.learner_public_id||'';localStorage.setItem('edumatrix_enterprise_journey_org',organizationId.value);localStorage.setItem('edumatrix_enterprise_journey_learner',learnerId.value)}
async function load(){loading.value=true;error.value='';try{workspace.value=await getEnterpriseJourneyWorkspace();if(selectedRunId.value&&!workspace.value.runs.some(item=>item.id===selectedRunId.value))selectedRunId.value='';if(!selectedRunId.value&&workspace.value.runs.length)selectedRunId.value=workspace.value.runs[0].id;if(run.value)applyRunContext(run.value);else{if(!organization.value)organizationId.value=workspace.value.organizations[0]?.id||'';if(!learners.value.some(item=>item.public_id===learnerId.value))learnerId.value=learners.value[0]?.public_id||''}if(selectedRunId.value)localStorage.setItem('edumatrix_enterprise_journey_id',selectedRunId.value)}catch(e){error.value=detail(e)}finally{loading.value=false}}
async function create(){action.value='create';error.value='';try{const created=await createEnterpriseJourney({organization_id:organizationId.value,learner_public_id:learnerId.value,run_key:`enterprise-judge-${Date.now()}`});selectedRunId.value=created.id;localStorage.setItem('edumatrix_enterprise_journey_id',created.id);applyRunContext(created);notice.value='企业培训旅程已建立，岗位标准、差距与培训分配已冻结';await load()}catch(e){error.value=detail(e)}finally{action.value=''}}
async function openStep(step){if(!run.value)return;action.value=step.key;error.value='';try{await recordEnterpriseJourneyVisit(run.value.id,{step_key:step.key,route:step.route});const context=run.value.enterprise_context||{};await router.push({path:step.route,query:{journey:run.value.id,organization_id:context.organization_id,learner_public_id:context.learner_public_id,assignment_id:context.assignment_id,step:step.key}})}catch(e){error.value=detail(e)}finally{action.value=''}}
function selectRun(id){selectedRunId.value=id;localStorage.setItem('edumatrix_enterprise_journey_id',id);applyRunContext(workspace.value.runs.find(item=>item.id===id))}
watch(organizationId,()=>{if(!learners.value.some(item=>item.public_id===learnerId.value))learnerId.value=learners.value[0]?.public_id||'';if(organizationId.value)localStorage.setItem('edumatrix_enterprise_journey_org',organizationId.value)})
watch(learnerId,value=>{if(value)localStorage.setItem('edumatrix_enterprise_journey_learner',value)})
onMounted(load)
</script>

<template><main class="journey"><header><div><p class="eyebrow"><Route :size="14"/> FC5 enterprise journey</p><h1>企业培训旅程</h1><p>合成岗位标准 → 转岗差距 → 培训批次 → 实操 → 演示签核 → 认证 → 到期复训。</p></div><button class="icon" aria-label="刷新企业培训旅程" title="刷新" @click="load"><RefreshCw :size="17"/></button></header>
<p v-if="error" class="notice error"><AlertCircle :size="15"/>{{error}}</p><p v-if="notice" class="notice ok"><BadgeCheck :size="15"/>{{notice}}</p><p v-if="loading" class="notice"><RefreshCw class="spin" :size="15"/>正在恢复企业培训旅程</p>
<section v-if="!loading&&workspace.truthfulness" class="truth"><ShieldCheck :size="18"/><div><strong>{{workspace.truthfulness.data_label}}</strong><span>{{workspace.truthfulness.review_label}}；页面访问不计完成，进度只读取服务端持久化证据。</span></div></section>
<template v-if="!loading"><section class="toolbar"><label><span>演示组织</span><select v-model="organizationId"><option value="" disabled>请选择可管理组织</option><option v-for="item in workspace.organizations" :key="item.id" :value="item.id">{{item.name}} · {{item.role}}</option></select></label><label><span>转岗学员</span><select v-model="learnerId" :disabled="!organizationId"><option value="" disabled>请选择组织内学员</option><option v-for="item in learners" :key="item.public_id" :value="item.public_id">{{item.display_name}}</option></select></label><label v-if="workspace.runs.length"><span>历史运行</span><select :value="run?.id||''" @change="selectRun($event.target.value)"><option value="" disabled>请选择运行</option><option v-for="item in workspace.runs" :key="item.id" :value="item.id">{{item.status}} · {{item.progress.completed}}/7 · {{item.run_key}}</option></select></label><button class="primary" :disabled="Boolean(action)||!organizationId||!learnerId" @click="create"><Play :size="14"/>新建培训旅程</button></section>
<section v-if="!run" class="empty"><BriefcaseBusiness :size="38"/><h2>尚未开始企业培训旅程</h2><p v-if="workspace.organizations.length">选择冻结合成组织和学员，建立可刷新恢复的七步运行。</p><p v-else>当前账号没有可管理的活动组织，请先在企业培训页初始化演示数据。</p></section>
<template v-else><section class="context"><div><span>岗位版本</span><strong>{{run.enterprise_context?.job_level_version}}</strong></div><div><span>冻结分配</span><strong>{{run.enterprise_context?.assignment_id}}</strong></div><div><span>数据边界</span><strong>冻结合成 · 本地演示</strong></div></section><section class="progress"><div><span>完成进度</span><strong>{{run.progress.completed}} / {{run.progress.total}}</strong></div><div class="bar"><i :style="{width:`${run.progress.percent}%`}"/></div><div><span>运行状态</span><strong>{{run.status==='completed'?'已完成':'进行中'}}</strong></div><button v-if="nextStep" class="primary" @click="openStep(nextStep)">继续：{{nextStep.label}}<ChevronRight :size="14"/></button><span v-else class="complete"><BadgeCheck :size="15"/>七步培训闭环完成</span></section>
<section class="steps"><article v-for="(step,index) in run.steps" :key="step.key" :class="{done:step.complete,next:nextStep?.key===step.key}"><div class="index"><BadgeCheck v-if="step.complete" :size="16"/><Circle v-else :size="16"/>{{index+1}}</div><div class="body"><span>{{step.key}}</span><strong>{{step.label}}</strong><p>{{step.purpose}}</p><small>{{step.summary}}</small><code v-if="step.evidence_id">{{step.evidence_id}}</code></div><button class="secondary" :disabled="Boolean(action)" @click="openStep(step)">{{step.complete?'查看证据':'进入工作台'}}<ChevronRight :size="14"/></button></article></section>
<section class="audit"><div><span>访问记录</span><strong>{{run.visits.length}}</strong></div><p>认证必须引用本次已通过的本地实操证据；最后一步只接受正式到期扫描生成的复训任务。演示角色签核不代表真实企业或外部专家认证。</p></section></template></template></main></template>

<style scoped>.journey{max-width:1240px;margin:auto;color:#20272a;padding:4px 2px 42px}.journey header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.journey h1{font-size:24px;margin:6px 0;letter-spacing:0}.journey header p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#53643e;font-size:10px;font-weight:750;text-transform:uppercase}.icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.notice{display:flex;align-items:center;gap:7px;padding:11px 14px;background:#f4f7f8;font-size:10px}.notice.error{background:#fff1ef;color:#963f35}.notice.ok{background:#eef8f1;color:#276046}.truth{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#f5f6e9;color:#56602d;border-bottom:1px solid #d8dcb8}.truth div{display:flex;flex-wrap:wrap;gap:5px 14px}.truth strong{font-size:11px}.truth span{font-size:10px}.toolbar{display:grid;grid-template-columns:1fr 1fr 1.2fr auto;align-items:end;gap:12px;padding:16px 0;border-bottom:1px solid #dce2e5}.toolbar label{display:flex;flex-direction:column;gap:5px;min-width:0}.toolbar label span{font-size:8px;color:#748087}.toolbar select{height:36px;border:1px solid #d4dcdf;background:#fff;padding:0 9px;font-size:10px;min-width:0;width:100%}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:6px;padding:9px 11px;font-size:10px;font-weight:650;cursor:pointer}.primary{background:#52653b;color:#fff}.primary:disabled,.secondary:disabled{opacity:.55;cursor:not-allowed}.secondary{background:#eff2e8;color:#52653b}.context{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid #dce2e5;background:#fafbf6}.context div{display:flex;min-width:0;flex-direction:column;padding:12px 15px;border-right:1px solid #e2e6d9}.context span{font-size:8px;color:#748087}.context strong{font-size:10px;overflow-wrap:anywhere}.progress{display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:16px;padding:17px;background:#f7f8f2;border-bottom:1px solid #dce2e5}.progress>div:not(.bar){display:flex;flex-direction:column}.progress span{font-size:8px;color:#748087}.progress strong{font-size:13px}.bar{height:6px;background:#e2e6d7;overflow:hidden}.bar i{display:block;height:100%;background:#687e47}.complete{display:flex!important;align-items:center;gap:6px;color:#276046!important;font-size:10px!important}.steps{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:22px 0}.steps article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;min-width:0;padding:15px;border:1px solid #dce2e5;background:#fff}.steps article.done{border-color:#bdd3c5;background:#f4faf6}.steps article.next{border-color:#b5c48f}.index{display:flex;flex-direction:column;align-items:center;gap:3px;color:#65747a;font-size:8px}.done .index{color:#276046}.body{display:flex;min-width:0;flex-direction:column}.body>span{font-size:7px;color:#667b43}.body strong{font-size:12px}.body p{font-size:9px;color:#748087;margin:3px 0}.body small{font-size:8px;color:#5f7067}.body code{margin-top:4px;font-size:7px;color:#748087;overflow-wrap:anywhere}.audit{display:flex;align-items:center;gap:16px;padding:14px;border:1px solid #dce2e5;background:#f8fafb}.audit div{display:flex;flex-direction:column;min-width:70px}.audit span{font-size:8px;color:#748087}.audit strong{font-size:15px}.audit p{font-size:9px;color:#667177}.empty{min-height:340px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:9px;color:#748087}.empty h2{font-size:15px;color:#20272a}.empty p{font-size:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.toolbar .primary{width:100%}}@media(max-width:800px){.toolbar,.context,.progress,.steps{grid-template-columns:1fr}.progress .primary{width:100%}.steps article{grid-template-columns:auto 1fr}.steps article button{grid-column:1/-1;width:100%}.context div{border-right:0;border-bottom:1px solid #e2e6d9}.audit{align-items:flex-start;flex-direction:column}}@media(max-width:430px){.journey h1{font-size:21px}.truth{align-items:flex-start}.toolbar select{width:100%}}</style>
